pub fn utility(request: &Value) -> Option<Result<Value, String>> {
    if !matches!(
        request.get("op").and_then(Value::as_str)?,
        "getTokens"
            | "columnNameFromNumber"
            | "columnNumberFromName"
            | "quoteName"
            | "getAllTimezones"
            | "getSupportedLocales"
            | "getThemeList"
            | "hexWithTintToRgb"
    ) {
        return None;
    }
    Some((|| match text(request, "op")? {
        "getTokens" => {
            value(upstream_api::get_tokens(text(request, "formula")?).map_err(|e| e.to_string())?)
        }
        "columnNameFromNumber" => value(
            upstream_api::column_name_from_number(arg(request, "column")?)
                .map_err(|e| e.to_string())?,
        ),
        "columnNumberFromName" => value(
            upstream_api::column_number_from_name(text(request, "column")?)
                .map_err(|e| e.to_string())?,
        ),
        "quoteName" => value(upstream_api::quote_name(text(request, "name")?)),
        "getAllTimezones" => value(upstream_api::get_all_timezones()),
        "getSupportedLocales" => value(upstream_api::get_supported_locales()),
        "getThemeList" => value(upstream_api::get_theme_list()),
        "hexWithTintToRgb" => value(upstream_api::hex_with_tint_to_rgb(
            text(request, "hex")?,
            arg(request, "tint")?,
        )),
        _ => unreachable!(),
    })())
}
